import React, { useState, useEffect } from 'react';
import { View, Text, StatusBar, SafeAreaView, TouchableOpacity, ScrollView, ActivityIndicator, Alert, TextInput, Platform, ImageBackground } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';
import api from '../../services/api';
import { useNavigation } from '@react-navigation/native';

// Fallback para MapView no Web
let MapView = View;
let Marker = View;
let Polyline = View;
let PROVIDER_GOOGLE = null;

try {
  const Maps = require('react-native-maps');
  MapView = Maps.default || Maps;
  Marker = Maps.Marker;
  Polyline = Maps.Polyline;
  PROVIDER_GOOGLE = Maps.PROVIDER_GOOGLE;
} catch (e) {
  console.warn("Maps not available, using fallback");
}

const Container = styled.View`
  flex: 1;
  background-color: ${colors.background};
`;

const DestinationOverlay = styled.View`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: ${colors.white};
  z-index: 1000;
  padding-top: ${Platform.OS === 'ios' ? 60 : 40}px;
`;

const SearchHeaderScroll = styled.View`
  flex-direction: row;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  margin-bottom: ${spacing.md}px;
`;

const SearchInput = styled.TextInput`
  flex: 1;
  height: 50px;
  background-color: #f0f0f0;
  border-radius: ${borderRadius.md}px;
  padding-horizontal: ${spacing.md}px;
  margin-left: ${spacing.md}px;
  font-size: 16px;
`;

const SearchResultList = styled.ScrollView`
  flex: 1;
`;

const SearchResultItem = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: #f5f5f5;
`;

const ResultIcon = styled.View`
  width: 40px;
  height: 40px;
  border-radius: 20px;
  background-color: #f0f0f0;
  justify-content: center;
  align-items: center;
  margin-right: ${spacing.md}px;
`;

const ResultTextContainer = styled.View`
  flex: 1;
`;

const ResultTitle = styled.Text`
  font-size: 16px;
  font-weight: 500;
  color: ${colors.text};
`;

const ResultSubtitle = styled.Text`
  font-size: 14px;
  color: ${colors.textSecondary};
`;

const HeaderContainer = styled.SafeAreaView`
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  background-color: transparent;
  z-index: 100;
`;

const TopBar = styled.View`
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  margin-top: ${Platform.OS === 'android' ? 40 : 10}px;
`;

const IconButton = styled.TouchableOpacity`
  width: 45px;
  height: 45px;
  border-radius: ${borderRadius.full}px;
  background-color: ${colors.white};
  justify-content: center;
  align-items: center;
  elevation: 8;
  shadow-color: #000;
  shadow-offset: 0px 4px;
  shadow-opacity: 0.2;
  shadow-radius: 5px;
`;

const SelectionHeader = styled.TouchableOpacity`
  background-color: ${colors.white};
  margin-horizontal: ${spacing.md}px;
  margin-top: ${spacing.sm}px;
  border-radius: ${borderRadius.lg}px;
  padding: ${spacing.md}px;
  elevation: 10;
  shadow-color: #000;
  shadow-offset: 0px 5px;
  shadow-opacity: 0.1;
  shadow-radius: 8px;
`;

const MapLabel = styled.TouchableOpacity`
  background-color: ${colors.white};
  padding: 8px 12px;
  border-radius: 12px;
  elevation: 8;
  shadow-color: #000;
  shadow-offset: 0px 4px;
  shadow-opacity: 0.3;
  shadow-radius: 5px;
  border-width: 1px;
  border-color: #f0f0f0;
  flex-direction: row;
  align-items: center;
  max-width: 180px;
`;

const LabelText = styled.Text`
  font-size: 11px;
  font-weight: bold;
  color: ${colors.text};
`;

const AddressLabelText = styled.Text`
  font-size: 10px;
  color: ${colors.textSecondary};
  margin-top: 2px;
`;

const SearchRow = styled.View`
  flex-direction: row;
  align-items: center;
`;

const DotContainer = styled.View`
  align-items: center;
  margin-right: ${spacing.sm}px;
`;

const Dot = styled.View`
  width: 8px;
  height: 8px;
  border-radius: 4px;
  background-color: ${props => props.color || colors.primary};
`;

const Line = styled.View`
  width: 1px;
  height: 20px;
  background-color: #ddd;
  margin-vertical: 2px;
`;

const SearchInputRow = styled.View`
  flex: 1;
`;

const AddressText = styled.Text`
  font-size: 14px;
  color: ${props => props.placeholder ? colors.textSecondary : colors.text};
  font-weight: ${props => props.placeholder ? '400' : '500'};
`;

const Divider = styled.View`
  height: 1px;
  background-color: #f0f0f0;
  margin-vertical: 6px;
`;

const CategoryItem = styled.TouchableOpacity`
  flex-direction: row;
  align-items: center;
  padding-vertical: ${spacing.md}px;
  border-bottom-width: 1px;
  border-bottom-color: #f5f5f5;
  background-color: ${props => props.selected ? '#fcfdfc' : 'transparent'};
`;

const CategoryInfo = styled.View`
  flex: 1;
  margin-horizontal: ${spacing.sm}px;
`;

const CategoryName = styled.Text`
  font-size: 16px;
  font-weight: bold;
`;

const CategoryPrice = styled.Text`
  font-size: 16px;
  font-weight: bold;
`;

const BottomSheet = styled.View`
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: ${colors.white};
  border-top-left-radius: 25px;
  border-top-right-radius: 25px;
  padding-top: ${spacing.sm}px;
  padding-bottom: ${Platform.OS === 'ios' ? 40 : 20}px;
  elevation: 30;
  shadow-color: #000;
  shadow-offset: 0px -10px;
  shadow-opacity: 0.1;
  shadow-radius: 15px;
  z-index: 50;
`;

const Handle = styled.View`
  width: 40px;
  height: 5px;
  background-color: #e0e0e0;
  border-radius: 3px;
  align-self: center;
  margin-vertical: ${spacing.sm}px;
`;

const ContentPadding = styled.View`
  padding-horizontal: ${spacing.lg}px;
`;

const Greeting = styled.Text`
  font-size: 20px;
  font-weight: bold;
  color: ${colors.text};
  margin-bottom: 4px;
`;

const MainSearchButton = styled.TouchableOpacity`
  background-color: ${colors.background};
  border-radius: ${borderRadius.lg}px;
  height: 55px;
  flex-direction: row;
  align-items: center;
  padding-horizontal: ${spacing.md}px;
  margin-top: ${spacing.md}px;
  border-width: 1px;
  border-color: ${colors.border};
`;

const ConfirmButton = styled.TouchableOpacity`
  background-color: #FFC107;
  height: 55px;
  border-radius: 30px;
  justify-content: center;
  align-items: center;
  margin-top: ${spacing.sm}px;
`;

const HomeScreen = () => {
  const navigation = useNavigation();
  const [isSelecting, setIsSelecting] = useState(false);
  const [isChoosingDestination, setIsChoosingDestination] = useState(false);
  const [isSelectingPayment, setIsSelectingPayment] = useState(false);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false);
  const [selectedCat, setSelectedCat] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState({ id: 'money', label: 'Dinheiro', icon: 'payments' });

  const [pickup, setPickup] = useState('Sua Localização (Alameda Itu)');
  const [destination, setDestination] = useState('');

  const [pickupCoords] = useState({ latitude: -23.5617, longitude: -46.6623 });
  const [destCoords, setDestCoords] = useState(null);
  const [rideDetails, setRideDetails] = useState({ distance: 0, time: 0, arrivalTime: 0 });
  const [routePoints, setRoutePoints] = useState([]);

  const mockLocations = [
    { title: 'Básico Materiais Para Const...', subtitle: 'Rua Augusta, 1500 - Consolação', coords: { latitude: -23.5505, longitude: -46.6333 } },
    { title: 'Shopping Cidade São Paulo', subtitle: 'Av. Paulista, 1230 - Bela Vista', coords: { latitude: -23.5644, longitude: -46.6527 } },
    { title: 'Parque do Ibirapuera', subtitle: 'Av. Pedro Álvares Cabral - Moema', coords: { latitude: -23.5874, longitude: -46.6576 } },
  ];

  const selectDestination = async (loc) => {
    setDestination(loc.title);
    setDestCoords(loc.coords);
    setIsChoosingDestination(false);
    setLoading(true);

    try {
      // Get real street route from OSRM
      const url = `https://router.project-osrm.org/route/v1/driving/${pickupCoords.longitude},${pickupCoords.latitude};${loc.coords.longitude},${loc.coords.latitude}?overview=full&geometries=geojson`;
      const response = await fetch(url);
      const json = await response.json();

      if (json.routes && json.routes.length > 0) {
        const coords = json.routes[0].geometry.coordinates.map(c => ({
          latitude: c[1],
          longitude: c[0]
        }));
        setRoutePoints(coords);

        // Update details based on real route
        const dist = (json.routes[0].distance / 1000).toFixed(1);
        const time = Math.ceil(json.routes[0].duration / 60);
        const arrival = Math.floor(Math.random() * 4 + 2);
        setRideDetails({ distance: dist, time, arrivalTime: arrival });
      } else {
        // Fallback zig-zag if OSRM fails
        setRoutePoints([pickupCoords, loc.coords]);
        setRideDetails({ distance: (Math.random() * 5 + 2).toFixed(1), time: Math.floor(Math.random() * 10 + 5), arrivalTime: 3 });
      }
    } catch (e) {
      console.error("Route error:", e);
      setRoutePoints([pickupCoords, loc.coords]);
    }

    loadCategories();
  };

  const loadCategories = async () => {
    setLoading(true);
    setIsSelecting(true);
    try {
      const response = await api.passenger.getCategories(1);
      if (response.data && Array.isArray(response.data)) {
        setCategories(response.data.map(cat => ({
            ...cat, 
            price: (Math.random() * 20 + 15).toFixed(2),
            time: Math.floor(Math.random() * 5 + 2)
        })));
        if (response.data.length > 0) setSelectedCat(response.data[0].id);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const toggleSelection = () => {
    setIsSelecting(false);
    setIsSelectingPayment(false);
    setDestination('');
    setDestCoords(null);
    setRoutePoints([]);
    setRideDetails({ distance: 0, time: 0, arrivalTime: 0 });
  };

  const renderMap = () => {
    if (Platform.OS === 'web') {
      return (
        <View style={{ flex: 1, backgroundColor: '#eef2f3', justifyContent: 'center', alignItems: 'center' }}>
          <Icon name="map" size={120} color="#cbd5e0" />
          <Text style={{ color: '#718096', marginTop: 15, fontSize: 18, fontWeight: '500' }}>Mapa Interativo (99 Style Mock)</Text>
        </View>
      );
    }

    return (
      <MapView 
        style={{ flex: 1 }}
        initialRegion={{
          latitude: -23.5617,
          longitude: -46.6623,
          latitudeDelta: 0.05,
          longitudeDelta: 0.05,
        }}
      >
        <Marker coordinate={pickupCoords} zIndex={2}>
           <View style={{ width: 14, height: 14, backgroundColor: '#2ecc71', borderRadius: 7, borderWidth: 3, borderColor: '#fff' }} />
        </Marker>

        {destCoords && (
          <>
            <Marker coordinate={destCoords} zIndex={3}>
               <View style={{ alignItems: 'center', justifyContent: 'center' }}>
                 <View style={{ width: 24, height: 24, backgroundColor: '#333', borderRadius: 12, justifyContent: 'center', alignItems: 'center' }}>
                    <View style={{ width: 8, height: 8, backgroundColor: '#fff', borderRadius: 4 }} />
                 </View>
                 <View style={{ width: 2, height: 10, backgroundColor: '#333' }} />
               </View>
            </Marker>

            <Polyline 
              coordinates={routePoints}
              strokeColor={colors.primary}
              strokeWidth={8}
              lineCap="round"
              lineJoin="round"
            />

            {/* Labels dynamically positioned on route - 99 Style */}
            {routePoints.length >= 2 && (
              <>
                <Marker coordinate={routePoints[0]} anchor={{ x: 0.5, y: 1.2 }} zIndex={10}>
                   <MapLabel activeOpacity={0.9} onPress={() => setIsChoosingDestination(true)}>
                      <View style={{ flex: 1 }}>
                        <LabelText>{rideDetails.arrivalTime} min</LabelText>
                        <AddressLabelText numberOfLines={1}>{pickup.split('(')[0]}</AddressLabelText>
                      </View>
                      <Icon name="chevron-right" size={14} color="#ccc" />
                   </MapLabel>
                </Marker>

                <Marker coordinate={routePoints[routePoints.length - 1]} anchor={{ x: 0.5, y: -0.2 }} zIndex={11}>
                   <MapLabel activeOpacity={0.9} onPress={() => setIsChoosingDestination(true)}>
                      <View style={{ flex: 1 }}>
                        <LabelText>{rideDetails.distance} km • {rideDetails.time} min</LabelText>
                        <AddressLabelText numberOfLines={1}>{destination}</AddressLabelText>
                      </View>
                      <Icon name="chevron-right" size={14} color="#ccc" />
                   </MapLabel>
                </Marker>
              </>
            )}
          </>
        )}
      </MapView>
    );
  };

  return (
    <Container>
      <StatusBar barStyle="dark-content" backgroundColor="transparent" translucent />

      {isChoosingDestination && (
        <DestinationOverlay>
          <SearchHeaderScroll>
            <TouchableOpacity onPress={() => setIsChoosingDestination(false)}>
              <Icon name="arrow-back" size={30} color={colors.text} />
            </TouchableOpacity>
            <SearchInput autoFocus placeholder="Informe o destino" />
          </SearchHeaderScroll>
          <SearchResultList>
            <ContentPadding>
              <Text style={{ fontSize: 13, fontWeight: 'bold', color: '#999', marginBottom: 10 }}>HISTÓRICO</Text>
              {mockLocations.map((loc, idx) => (
                <SearchResultItem key={idx} onPress={() => selectDestination(loc)}>
                  <ResultIcon><Icon name="history" size={20} color="#666" /></ResultIcon>
                  <ResultTextContainer>
                    <ResultTitle>{loc.title}</ResultTitle>
                    <ResultSubtitle>{loc.subtitle}</ResultSubtitle>
                  </ResultTextContainer>
                </SearchResultItem>
              ))}
            </ContentPadding>
          </SearchResultList>
        </DestinationOverlay>
      )}

      <HeaderContainer pointerEvents="box-none">
        <TopBar pointerEvents="box-none">
          <IconButton onPress={() => {
            if (isSelectingPayment) setIsSelectingPayment(false);
            else if (isSelecting) toggleSelection();
            else Alert.alert('Menu', 'Abrindo perfil...');
          }}>
            <Icon name={(isSelecting || isSelectingPayment) ? "arrow-back" : "menu"} size={28} color={colors.secondary} />
          </IconButton>

          {!isSelecting && (
            <IconButton onPress={() => Alert.alert('Chat', 'Sem conversas agora.')}>
              <Icon name="chat" size={24} color={colors.secondary} />
            </IconButton>
          )}
        </TopBar>
      </HeaderContainer>

      {renderMap()}

      <BottomSheet expanded={isSelecting}>
        <Handle />
        <ContentPadding>
          {!isSelecting ? (
            <>
              <Greeting>Olá, Passageiro!</Greeting>
              <Text style={{ color: colors.textSecondary }}>Para onde vamos hoje?</Text>
              <MainSearchButton activeOpacity={0.8} onPress={() => setIsChoosingDestination(true)}>
                <Icon name="search" size={24} color={colors.primary} />
                <Text style={{ flex: 1, marginLeft: 10, color: '#aaa', fontSize: 16 }}>Qual seu destino?</Text>
              </MainSearchButton>
              <View style={{ marginTop: 20, flexDirection: 'row', justifyContent: 'space-around' }}>
                <TouchableOpacity style={{ alignItems: 'center' }}><Icon name="home" size={24} color="#666" /><Text style={{ fontSize: 12 }}>Casa</Text></TouchableOpacity>
                <TouchableOpacity style={{ alignItems: 'center' }}><Icon name="work" size={24} color="#666" /><Text style={{ fontSize: 12 }}>Trabalho</Text></TouchableOpacity>
              </View>
            </>
          ) : isSelectingPayment ? (
            <>
              <Text style={{ fontSize: 18, fontWeight: 'bold', marginBottom: 20 }}>Pagamento</Text>
              <ScrollView style={{ maxHeight: 300 }}>
                {paymentOptions.map((opt) => (
                  <TouchableOpacity key={opt.id} onPress={() => { setPaymentMethod(opt); setIsSelectingPayment(false); }} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15, borderBottomWidth: 1, borderBottomColor: '#eee' }}>
                    <Icon name={opt.icon} size={28} color={paymentMethod.id === opt.id ? "#f39c12" : "#aaa"} />
                    <Text style={{ flex: 1, marginLeft: 15, fontSize: 16 }}>{opt.label}</Text>
                    {paymentMethod.id === opt.id && <Icon name="check-circle" size={24} color={colors.primary} />}
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </>
          ) : (
            <>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                <Text style={{ fontSize: 16, fontWeight: 'bold' }}>Opções de Viagem</Text>
                <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                  <Icon name="timer" size={14} color="#999" />
                  <Text style={{ fontSize: 12, color: '#999', marginLeft: 4 }}>{rideDetails.time} min • {rideDetails.distance} km</Text>
                </View>
              </View>

              {loading ? (
                <ActivityIndicator size="large" color={colors.primary} style={{ marginVertical: 30 }} />
              ) : (
                <ScrollView style={{ maxHeight: 250 }} showsVerticalScrollIndicator={false}>
                  {categories.map((cat) => (
                    <CategoryItem 
                      key={cat.id} 
                      selected={selectedCat === cat.id}
                      onPress={() => setSelectedCat(cat.id)}
                    >
                      <View style={{ width: 50, height: 40, justifyContent: 'center', alignItems: 'center' }}>
                         <Icon name="directions-car" size={35} color={selectedCat === cat.id ? colors.primary : '#aaa'} />
                      </View>
                      <CategoryInfo>
                        <CategoryName>{cat.nome}</CategoryName>
                        <Text style={{ fontSize: 12, color: '#999' }}>Chega em {rideDetails.arrivalTime} min</Text>
                      </CategoryInfo>
                      <View style={{ alignItems: 'flex-end' }}>
                        <CategoryPrice>R$ {cat.tx_base || '14,90'}</CategoryPrice>
                        <Text style={{ fontSize: 10, color: colors.primary, fontWeight: '600' }}>{Math.random() > 0.5 ? 'BARATO' : 'RÁPIDO'}</Text>
                      </View>
                    </CategoryItem>
                  ))}
                </ScrollView>
              )}

              <TouchableOpacity onPress={() => setIsSelectingPayment(true)} style={{ flexDirection: 'row', alignItems: 'center', paddingVertical: 15 }}>
                <View style={{ backgroundColor: '#fff8e1', padding: 6, borderRadius: 8 }}>
                  <Icon name={paymentMethod.icon} size={20} color="#f39c12" />
                </View>
                <Text style={{ flex: 1, marginLeft: 10, fontWeight: '500' }}>{paymentMethod.label} • Alterar</Text>
                <Icon name="chevron-right" size={20} color="#ccc" />
              </TouchableOpacity>

              <ConfirmButton onPress={() => Alert.alert('Sucesso', 'Procurando motorista...')} activeOpacity={0.9}>
                <Text style={{ color: colors.secondary, fontSize: 18, fontWeight: 'bold' }}>
                  CONFIRMAR {categories.find(c => c.id === selectedCat)?.nome?.toUpperCase() || 'VIAGEM'}
                </Text>
              </ConfirmButton>
            </>
          )}
        </ContentPadding>
      </BottomSheet>
    </Container>
  );
};

export default HomeScreen;
